<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\SchemaUpdater;Auth::requirePermission('registrations.manage');$pdo=Database::connection();$error='';$notice='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$id=(int)$_POST['id'];$s=$pdo->prepare('SELECT registration_status,payment_status FROM bdc_event_registrations WHERE id=:id');$s->execute(['id'=>$id]);$old=$s->fetch();if(!$old)throw new RuntimeException('Registration not found.');$action=$_POST['action'];$rs=$old['registration_status'];$ps=$old['payment_status'];if($action==='approve'){$rs='approved';$ps='verified';}elseif($action==='reject'){$rs='rejected';$ps='rejected';}elseif($action==='more_info'){$rs='more_information';}elseif($action==='cancel'){$rs='cancelled';}elseif($action==='cash_received'){$rs='approved';$ps='verified';}$pdo->beginTransaction();$pdo->prepare('UPDATE bdc_event_registrations SET registration_status=:rs,payment_status=:ps,admin_notes=:notes WHERE id=:id')->execute(['rs'=>$rs,'ps'=>$ps,'notes'=>trim((string)($_POST['notes']??'')),'id'=>$id]);$pdo->prepare('UPDATE bdc_registration_payments SET verification_status=:ps,verified_by=:uid,verified_at=CASE WHEN :ps2=\'verified\' THEN NOW() ELSE verified_at END,admin_notes=:notes WHERE registration_id=:id')->execute(['ps'=>$ps,'uid'=>(int)Auth::user()['id'],'ps2'=>$ps,'notes'=>trim((string)($_POST['notes']??'')),'id'=>$id]);$pdo->prepare('INSERT INTO bdc_registration_history(registration_id,old_registration_status,new_registration_status,old_payment_status,new_payment_status,notes,changed_by) VALUES(:id,:ors,:nrs,:ops,:nps,:notes,:uid)')->execute(['id'=>$id,'ors'=>$old['registration_status'],'nrs'=>$rs,'ops'=>$old['payment_status'],'nps'=>$ps,'notes'=>trim((string)($_POST['notes']??'')),'uid'=>(int)Auth::user()['id']]);$pdo->commit();$notice='Registration updated.';}}
catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
$q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$event=(int)($_GET['event']??0);$where=[];$params=[];if($q!==''){$where[]='(LOWER(r.full_name) LIKE LOWER(:q) OR LOWER(r.email) LIKE LOWER(:q2) OR LOWER(r.registration_number) LIKE LOWER(:q3))';$params=['q'=>'%'.$q.'%','q2'=>'%'.$q.'%','q3'=>'%'.$q.'%'];}if($status!==''){$where[]='r.registration_status=:status';$params['status']=$status;}if($event){$where[]='r.event_id=:event';$params['event']=$event;}$sql='SELECT r.*,e.name event_name,e.event_date,t.name ticket_name,t.price,t.currency,p.payment_method,p.paid_amount,p.payment_reference,u.id upload_id FROM bdc_event_registrations r JOIN bdc_events e ON e.id=r.event_id JOIN bdc_event_ticket_types t ON t.id=r.ticket_type_id LEFT JOIN bdc_registration_payments p ON p.registration_id=r.id LEFT JOIN bdc_registration_uploads u ON u.registration_id=r.id '.($where?'WHERE '.implode(' AND ',$where):'').' ORDER BY r.created_at DESC LIMIT 500';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$events=$pdo->query('SELECT id,name,event_date FROM bdc_events ORDER BY event_date DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registrations | BDC Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../">BDC Admin</a><a class="btn btn-outline-light btn-sm" href="../events/">Events & Tickets</a></div></nav><main class="container-fluid py-4 px-lg-5"><h1 class="h3">Event Registrations</h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><form class="row g-2 mb-3"><div class="col-md-4"><input class="form-control" name="q" placeholder="Name, email or registration number" value="<?=e($q)?>"></div><div class="col-md-3"><select class="form-select" name="event"><option value="0">All events</option><?php foreach($events as $ev):?><option value="<?=$ev['id']?>" <?=$event===$ev['id']?'selected':''?>><?=e($ev['event_date'].' — '.$ev['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['pending_verification','approved','rejected','more_information','cancelled','checked_in','no_show'] as $v):?><option <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-dark w-100">Filter</button></div></form><div class="table-responsive bg-white shadow-sm rounded"><table class="table table-hover align-middle mb-0"><thead><tr><th>Registration</th><th>Event</th><th>Ticket</th><th>Payment</th><th>Status</th><th>Receipt</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['full_name'])?></strong><div class="small"><?=e($r['registration_number'])?> · <?=e($r['email'])?> · <?=e($r['phone'])?></div><div class="small text-muted"><?=e($r['dance_category'])?>, <?=e($r['dance_role'])?></div></td><td><?=e($r['event_name'])?><div class="small text-muted"><?=e((string)$r['event_date'])?></div></td><td><?=e($r['ticket_name'])?><div class="small"><?=e($r['currency'])?> <?=number_format((float)$r['price'],2)?></div></td><td><?=e($r['payment_method'])?><div class="small">Paid: <?=e((string)$r['paid_amount'])?> · Ref: <?=e((string)$r['payment_reference'])?></div><span class="badge text-bg-info"><?=e($r['payment_status'])?></span></td><td><span class="badge text-bg-secondary"><?=e($r['registration_status'])?></span></td><td><?php if($r['upload_id']):?><a class="btn btn-sm btn-outline-primary" target="_blank" href="../registration-file/?id=<?=$r['upload_id']?>">Open</a><?php else:?>—<?php endif;?></td><td><form method="post" class="d-flex flex-wrap gap-1"><?=Csrf::field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input class="form-control form-control-sm" style="width:140px" name="notes" placeholder="Admin note"><button class="btn btn-sm btn-success" name="action" value="approve">Approve</button><button class="btn btn-sm btn-warning" name="action" value="more_info">More info</button><button class="btn btn-sm btn-danger" name="action" value="reject">Reject</button><?php if($r['payment_method']==='cash'):?><button class="btn btn-sm btn-primary" name="action" value="cash_received">Cash received</button><?php endif;?></form></td></tr><?php endforeach;?></tbody></table></div></main></body></html>
